<script setup lang="ts">
import {onMounted, ref} from "vue"
import {RouterLink} from "vue-router"
import type {BusinessOfferingRequestDTO, BusinessOfferingResponseDTO, BusinessOfferingSetupDTO} from "../../../contracts/index.ts"
import {setActiveBusinessProfileId, userShellApi} from "../api/userShellApi.ts"
import AppDialog from "../components/AppDialog.vue"
import AppButton from "../components/AppButton.vue"
import AppFormField from "../components/AppFormField.vue"
import AppFormFooter from "../components/AppFormFooter.vue"
import AppStatus from "../components/AppStatus.vue"
import CollectionToolbar from "../components/CollectionToolbar.vue"
import SurfaceRow from "../components/SurfaceRow.vue"
import {confirmAction} from "../composables/useActionDialog.ts"

const props = defineProps<{businessId?: number}>()

const offerings = ref<BusinessOfferingResponseDTO[]>([])
const setup = ref<BusinessOfferingSetupDTO | null>(null)
// Offering visibility is represented by the server-provided active state.
const form = ref<BusinessOfferingRequestDTO | null>(null)
const editingId = ref<number | null>(null)
const isLoading = ref(true)
const isSaving = ref(false)
const error = ref("")
const feedback = ref("")

const emptyForm = (): BusinessOfferingRequestDTO | null => setup.value ? {...setup.value.defaults, sortOrder: offerings.value.length} : null
const load = async () => { isLoading.value = true; error.value = ""; try { if (props.businessId) setActiveBusinessProfileId(props.businessId); setup.value = await userShellApi.getBusinessOfferingSetup(props.businessId); offerings.value = (await userShellApi.getBusinessOfferings()).items } catch { error.value = "Could not load offerings." } finally { isLoading.value = false } }
const beginCreate = () => { editingId.value = null; form.value = emptyForm(); feedback.value = "" }
const beginEdit = (offering: BusinessOfferingResponseDTO) => { editingId.value = offering.id; form.value = {...offering}; feedback.value = "" }
const save = async () => { if (!form.value) return; isSaving.value = true; error.value = ""; try { if (editingId.value) await userShellApi.updateBusinessOffering(editingId.value, form.value); else await userShellApi.createBusinessOffering(form.value); form.value = null; feedback.value = "Offering saved."; await load() } catch { error.value = "Could not save this offering." } finally { isSaving.value = false } }
const remove = async (offering: BusinessOfferingResponseDTO) => { if (!await confirmAction(`Delete ${offering.title}?`, "Delete offering")) return; isSaving.value = true; error.value = ""; try { await userShellApi.deleteBusinessOffering(offering.id); feedback.value = "Offering deleted."; await load() } catch { error.value = "Could not delete this offering." } finally { isSaving.value = false } }
onMounted(() => void load())
</script>

<template>
  <section class="offerings-surface">
    <CollectionToolbar title="Bookable services" :count="offerings.length" :busy="isLoading"><template #actions><AppButton type="button" tone="primary" @click="beginCreate">New offering</AppButton></template></CollectionToolbar>
    <AppStatus v-if="feedback" :message="feedback" tone="success" /><AppStatus v-if="isLoading" message="Loading offerings." busy /><AppStatus v-else-if="error && !form" :message="error" tone="error" retry @retry="load" /><AppStatus v-else-if="offerings.length === 0 && !form" message="No offerings yet. Create the first one." />
    <div v-else class="offerings-surface__workspace"><div class="offerings-surface__list"><SurfaceRow v-for="offering in offerings" :key="offering.id" :row="{id: String(offering.id), title: offering.title, description: offering.summary || 'No summary', badge: offering.active ? 'Active' : 'Inactive', meta: `${offering.basePriceAmount} ${offering.basePriceCurrency} · ${offering.defaultDurationMinutes} min`}"><template #actions><RouterLink class="offerings-surface__setup-link" :to="{path: '/business/service-setup', query: {businessId: props.businessId ? String(props.businessId) : undefined, offeringId: String(offering.id)}}">Booking rules</RouterLink><AppButton type="button" tone="secondary" @click.stop="beginEdit(offering)">Edit</AppButton><AppButton type="button" tone="danger" @click.stop="remove(offering)">Delete</AppButton></template></SurfaceRow></div></div>
    <AppDialog :open="form !== null" :title="editingId ? 'Edit service' : 'Add a service'" layout="workspace" @close="form = null"><form class="offerings-surface__form" @submit.prevent="save"><header class="offerings-surface__form-intro"><p class="offerings-surface__eyebrow">Customer-facing service</p><h2>Start with the essentials</h2><p>Customers need to know what the service is, how long it takes, what it costs, and whether you confirm requests.</p></header><AppFormField label="Service name" required><input v-model="form!.title" required maxlength="120" aria-label="Service name" placeholder="e.g. Full haircut"></AppFormField><AppFormField label="Short description" required hint="A sentence customers see before they book."><input v-model="form!.summary" required maxlength="240" aria-label="Short description" placeholder="Wash, cut and finish"></AppFormField><AppFormField label="More details" optional><textarea v-model="form!.description" maxlength="4000" placeholder="Anything useful customers should know before booking."></textarea></AppFormField><section class="offerings-surface__form-section"><h3>Price</h3><div class="offerings-surface__grid"><AppFormField label="How do you price this service?"><select v-model="form!.pricingType"><option v-for="option in setup?.pricingTypes" :key="option.value" :value="option.value">{{ option.label }}</option></select></AppFormField><AppFormField v-if="form!.pricingType !== 'FREE'" :label="form!.pricingType === 'FROM' ? 'Starting price' : 'Price'"><input v-model.number="form!.basePriceAmount" type="number" min="0" step="0.01"></AppFormField><AppFormField v-if="form!.pricingType !== 'FREE'" label="Currency" required><input v-model="form!.basePriceCurrency" required maxlength="3"></AppFormField></div></section><section class="offerings-surface__form-section"><h3>Appointment</h3><div class="offerings-surface__grid"><AppFormField label="How long does it take?" required><select v-model.number="form!.defaultDurationMinutes"><option v-for="option in setup?.durationOptions" :key="option.value" :value="Number(option.value)">{{ option.label }}</option></select></AppFormField><AppFormField label="How should bookings work?"><select v-model="form!.bookingMode"><option v-for="option in setup?.bookingModes" :key="option.value" :value="option.value">{{ option.label }}</option></select></AppFormField></div></section><details class="offerings-surface__advanced"><summary>More options</summary><p>Only change these when your service needs a special booking setup.</p><AppFormField label="Public link"><input v-model="form!.slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" aria-label="Public link"></AppFormField><div class="offerings-surface__grid"><AppFormField label="Customer chooses duration"><select v-model="form!.durationMode"><option value="FIXED">No, use the appointment length above</option><option value="CUSTOMER_SELECTS">Yes, let the customer choose</option><option value="ALL_DAY">This is an all-day service</option></select></AppFormField><AppFormField label="Time between appointments"><input v-model.number="form!.bufferAfterMinutes" type="number" min="0"></AppFormField><AppFormField label="Time needed before an appointment"><input v-model.number="form!.bufferBeforeMinutes" type="number" min="0"></AppFormField></div><div v-if="form!.durationMode === 'CUSTOMER_SELECTS'" class="offerings-surface__grid"><AppFormField label="Shortest appointment"><input v-model.number="form!.minDurationMinutes" type="number" min="1"></AppFormField><AppFormField label="Longest appointment"><input v-model.number="form!.maxDurationMinutes" type="number" min="1"></AppFormField><AppFormField label="Duration steps"><input v-model.number="form!.durationIncrementMinutes" type="number" min="1"></AppFormField></div><div class="offerings-surface__grid"><AppFormField label="Group appointments"><select v-model="form!.capacityMode"><option value="SINGLE">One customer at a time</option><option value="SHARED">More than one customer at a time</option></select></AppFormField><AppFormField v-if="form!.capacityMode === 'SHARED'" label="Customers per time"><input v-model.number="form!.slotCapacity" type="number" min="1"></AppFormField><AppFormField label="Service type"><select v-model="form!.fulfillmentMode"><option v-for="option in setup?.fulfillmentModes" :key="option.value" :value="option.value">{{ option.label }}</option></select></AppFormField></div><label class="offerings-surface__toggle"><input v-model="form!.active" type="checkbox"> This service is visible to customers</label></details><AppStatus v-if="error" :message="error" tone="error" /><AppFormFooter><template #secondary><AppButton type="button" tone="secondary" @click="form = null">Cancel</AppButton></template><template #primary><AppButton type="submit" tone="primary" :loading="isSaving">{{ isSaving ? "Saving" : editingId ? "Save changes" : "Add service" }}</AppButton></template></AppFormFooter></form><template #utility><p>{{ setup?.readinessMessage }}</p></template></AppDialog>
  </section>
</template>

<style scoped>
.offerings-surface{display:grid;gap:var(--space-3);max-width:none}.offerings-surface__header{display:flex;justify-content:space-between;align-items:end;gap:var(--space-3)}.offerings-surface__eyebrow{margin:0 0 var(--space-1);color:var(--text-soft);font-size:var(--text-size-label);font-weight:var(--text-weight-semibold);letter-spacing:var(--tracking-label);text-transform:uppercase}h1{margin:0;font-size:var(--text-size-page-title);letter-spacing:var(--tracking-tight)}h2{margin:0;font-size:var(--text-size-title)}.offerings-surface__list{display:grid;gap:0;border:1px solid var(--border-subtle);border-radius:var(--radius-surface);overflow:hidden}.offerings-surface__row{display:flex;justify-content:space-between;gap:var(--space-3);align-items:center;padding:var(--space-2) var(--space-3);border:1px solid var(--border-subtle);background:var(--surface-base)}.offerings-surface__row>div:first-child{display:grid;gap:var(--space-1);min-width:0}.offerings-surface__row span{color:var(--text-muted);font-size:var(--text-size-meta)}.offerings-surface__actions{display:flex;gap:var(--space-1)}.offerings-surface button{border:1px solid var(--control-border);border-radius:var(--radius-control);padding:var(--space-1) var(--space-2);background:var(--control-bg);color:var(--control-ink);font:inherit;font-size:var(--text-size-meta);font-weight:var(--text-weight-semibold);cursor:pointer;white-space:nowrap}.offerings-surface button:hover{border-color:var(--control-border-active);background:var(--control-bg-hover)}.offerings-surface__primary{border-color:var(--accent)!important;background:var(--accent)!important;color:var(--canvas)}.offerings-surface__danger{color:var(--danger)}.offerings-surface__secondary{margin-left:var(--space-1)}.offerings-surface__form{display:grid;gap:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-surface);background:var(--surface-base);padding:var(--space-3)}.offerings-surface__form label{display:grid;gap:var(--space-1);font-size:var(--text-size-meta);font-weight:var(--text-weight-semibold);color:var(--text-muted)}.offerings-surface__form input,.offerings-surface__form textarea{border:1px solid var(--control-border);border-radius:var(--radius-control);padding:var(--space-2);background:var(--control-bg);color:var(--control-ink);font:inherit;font-weight:400}.offerings-surface__form textarea{min-height:6rem}.offerings-surface__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--space-2)}.offerings-surface__toggle{display:flex!important;align-items:center;gap:var(--space-2)!important}.offerings-surface__toggle input{width:auto}.offerings-surface__feedback{margin:0;color:var(--success)}.offerings-surface__status{padding:var(--space-2) 0;color:var(--text-muted)}.offerings-surface__status--error{color:var(--danger)}.offerings-surface__status button{margin-left:var(--space-1);border:0;background:transparent;color:inherit;text-decoration:underline}@media(max-width:620px){.offerings-surface__row{align-items:start;flex-direction:column}.offerings-surface__grid{grid-template-columns:1fr}}
/* Workspace visual remediation: retain route behavior, replace legacy pill/card geometry. */
.offerings-surface{gap:var(--space-3);max-width:none}.offerings-surface__header{gap:var(--space-3)}.offerings-surface__eyebrow{margin:0 0 var(--space-1);color:var(--text-soft);font-size:var(--text-size-label);font-weight:var(--text-weight-semibold);letter-spacing:var(--tracking-label)}h1{font-size:var(--text-size-page-title);letter-spacing:var(--tracking-tight)}.offerings-surface__list{gap:0;border:1px solid var(--border-subtle);border-radius:var(--radius-surface);overflow:hidden}.offerings-surface button{border-radius:var(--radius-control);padding:var(--space-1) var(--space-2);font-size:var(--text-size-meta)}.offerings-surface__form input,.offerings-surface__form textarea{border-radius:var(--radius-control);padding:var(--space-2);background:var(--control-bg)}
/* Offering rows and forms use the same dense collection/control contract as other workspace routes. */
.offerings-surface__row { background: var(--surface-base); }
.offerings-surface__form { gap: var(--space-3); padding-top: var(--space-3); border-color: var(--border-subtle); }
.offerings-surface__form input,
.offerings-surface__form textarea { border-color: var(--control-border); color: var(--control-ink); }
.offerings-surface__setup-link{align-self:center;color:var(--accent);font-size:var(--text-size-meta);font-weight:var(--text-weight-semibold)}
.offerings-surface .app-button { border-radius:var(--radius-control); padding:var(--space-1) var(--space-3); background:var(--control-bg); color:var(--control-ink); }
.offerings-surface .app-button--primary { border-color:var(--accent); background:var(--accent); color:var(--canvas); }
.offerings-surface .app-button--danger { color:var(--danger); }
.offerings-surface__row { padding: var(--space-2) var(--space-3); background: var(--surface-base); }
.offerings-surface__form { border: 1px solid var(--border-subtle); border-radius: var(--radius-surface); background: var(--surface-base); padding: var(--space-3); }
.offerings-surface__form input, .offerings-surface__form textarea { background: var(--control-bg); }
.offerings-surface__workspace{display:grid;grid-template-columns:minmax(0,1fr)}
</style>
